  const [error, setError] = useState('Could not load your invoices.');
  const [loading, setLoading] = useState(false);

  function handleTryAgain() {
    if (loading) return;
    setLoading(true);
    // Stands in for the request to the server.
    setTimeout(() => {
      setLoading(false);
